import type { College, Course, Department, Program } from './types'

export interface CurriculumRow {
  programId: string
  courseId: string
  level: number
  semester: 1 | 2
}

/** Normalised UCC catalogue, generated by scripts/build-catalog.mjs. */
export interface Catalog {
  colleges: College[]
  departments: Department[]
  programs: Program[]
  courses: Course[]
  curriculum: CurriculumRow[]
}

export async function loadCatalog(): Promise<Catalog> {
  const mod = await import('./demo/catalog.json')
  return mod.default as Catalog
}
